const A=document.getElementById('app');
const seed=[
{id:1,name:'Cabaña del Lago',commune:'Pucón',region:'Araucanía',price:65000,cap:4,type:'Cabaña',bedrooms:2,beds:3,services:['Wifi','Estacionamiento','Cocina'],checkin:'15:00',checkout:'11:00',cancel:'Cancelación flexible hasta 48 horas antes.',img:'https://images.unsplash.com/photo-1449158743715-0a90ebb6d2d8?auto=format&fit=crop&w=800&q=80'},
{id:2,name:'Refugio Bosque Nativo',commune:'Villarrica',region:'Araucanía',price:72000,cap:5,type:'Cabaña',bedrooms:2,beds:4,services:['Wifi','Cocina','Calefacción'],checkin:'15:00',checkout:'11:00',cancel:'Cancelación flexible hasta 48 horas antes.',img:'https://images.unsplash.com/photo-1510798831971-661eb04b3739?auto=format&fit=crop&w=800&q=80'},
{id:3,name:'Hotel Mirador',commune:'Puerto Varas',region:'Los Lagos',price:89000,cap:2,type:'Hotel',bedrooms:1,beds:1,services:['Wifi','Desayuno','Estacionamiento'],checkin:'15:00',checkout:'11:00',cancel:'Cancelación flexible hasta 48 horas antes.',img:'https://images.unsplash.com/photo-1566073771259-6a8506099945?auto=format&fit=crop&w=800&q=80'},
{id:4,name:'Cabaña Costa Sur',commune:'Pichilemu',region:"O'Higgins",price:59000,cap:4,type:'Cabaña',bedrooms:2,beds:3,services:['Wifi','Estacionamiento','Parrilla'],checkin:'15:00',checkout:'11:00',cancel:'Cancelación flexible hasta 48 horas antes.',img:'https://images.unsplash.com/photo-1499793983690-e29da59ef1c2?auto=format&fit=crop&w=800&q=80'}];
let listings=JSON.parse(localStorage.getItem('findeListings')||'null')||seed;
let reservations=JSON.parse(localStorage.getItem('findeReservations')||'[]');
let ownerBlocks=JSON.parse(localStorage.getItem('findeOwnerBlocks')||'[]');
function saveOwnerBlocks(){localStorage.setItem('findeOwnerBlocks',JSON.stringify(ownerBlocks))}
function manualOverlap(id,a,b){return ownerBlocks.some(v=>v.listingId==id && a<v.checkout && b>v.checkin)}

let pendingPhotos=[];
let s={dest:'',a:null,b:null,ad:2,ni:0,cal:false,g:false,m:10,y:2026,sug:false};
const money=n=>'$'+Number(n).toLocaleString('es-CL'),fmt=x=>x?new Date(x+'T12:00').toLocaleDateString('es-CL',{day:'2-digit',month:'short'}):'Seleccionar';
function save(){localStorage.setItem('findeListings',JSON.stringify(listings))}
function saveReservations(){localStorage.setItem('findeReservations',JSON.stringify(reservations))}
function overlaps(id,a,b){return reservations.some(r=>r.listingId==id && r.status==='Confirmada' && a<r.checkout && b>r.checkin)||manualOverlap(id,a,b)}
function amenityList(x){return (x.services&&x.services.length?x.services:['Wifi','Estacionamiento']).slice(0,8)}
function availableListings(){return listings.filter(x=>x.active!==false)}
function validRut(v){v=(v||'').replace(/\./g,'').replace(/-/g,'').toUpperCase();if(!/^\d{7,8}[0-9K]$/.test(v))return false;let body=v.slice(0,-1),dv=v.slice(-1),sum=0,m=2;for(let i=body.length-1;i>=0;i--){sum+=Number(body[i])*m;m=m===7?2:m+1}let x=11-(sum%11),calc=x===11?'0':x===10?'K':String(x);return dv===calc}
function validDocument(type,value){value=(value||'').trim();if(type==='RUT')return validRut(value);return value.length>=4}
function validEmail(v){return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)}
function bookingCode(id){return 'FD-'+String(id).slice(-6)}
function destinations(q=''){let map={};availableListings().forEach(x=>{let k=x.commune+'|'+x.region;if(!map[k])map[k]={commune:x.commune,region:x.region,count:0};map[k].count++});return Object.values(map).filter(x=>(x.commune+' '+x.region).toLowerCase().includes(q.toLowerCase())).sort((a,b)=>b.count-a.count)}
function card(x){return `<div class="card clickable" onclick="detail(${x.id})"><img src="${(x.photos&&x.photos.length?x.photos[0]:x.img)}"><div class="pad"><h3>${x.name}</h3><p class="muted">${x.commune}, ${x.region} · hasta ${x.cap} huéspedes</p><span class="price">${money(x.price)} / noche</span><div class="openhint">Ver alojamiento →</div></div></div>`}
function home(){A.innerHTML=`<section class="hero"><h1>Encuentra tu próxima escapada</h1><p>Encuentra alojamientos disponibles, compara opciones y reserva tu estadía en pocos pasos.</p><div class="searchbar"><div class="field"><small>DESTINO</small><input id="dest" autocomplete="off" placeholder="¿A dónde quieres ir?" value="${s.dest}" onfocus="showSug()" oninput="showSug(this.value)">${s.sug?suggestions():''}</div><div class="field" onclick="cal()"><small>ENTRADA</small>${fmt(s.a)}</div><div class="field" onclick="cal()"><small>SALIDA</small>${fmt(s.b)}</div><div class="field" onclick="guest()"><small>HUÉSPEDES</small>${s.ad+s.ni} huésped(es)</div><button onclick="search()">Buscar</button>${s.cal?calendar():''}${s.g?guestbox():''}</div></section><section class="section"><h2>Destinos con alojamientos disponibles</h2><p class="muted">Mostramos únicamente destinos donde actualmente existen alojamientos publicados.</p><div class="cards">${destinations().map(d=>`<div class="box" style="cursor:pointer" onclick="choose('${d.commune}')"><h3>📍 ${d.commune}</h3><p class="muted">${d.region}</p><b>${d.count} alojamiento${d.count>1?'s':''}</b></div>`).join('')}</div></section><section class="section"><h2>Alojamientos destacados</h2><div class="cards">${availableListings().slice(0,8).map(card).join('')}</div></section>`;scrollTo(0,0)}
function showSug(q=''){let e=document.getElementById('dest');if(e)s.dest=e.value;s.sug=true;let field=e&&e.closest('.field');if(field){let old=field.querySelector('.suggest');if(old)old.remove();field.insertAdjacentHTML('beforeend',suggestions())}}
function suggestions(){let ds=destinations(s.dest);return `<div class="suggest">${ds.length?ds.map(d=>`<div class="suggest-option" onmousedown="event.preventDefault();event.stopPropagation();choose('${d.commune.replace(/'/g,"\\'")}')"><b>📍 ${d.commune}, ${d.region}</b><small>${d.count} alojamiento${d.count>1?'s':''} disponible${d.count>1?'s':''}</small></div>`).join(''):`<div><b>Sin oferta en este destino</b><small>Solo mostramos lugares con alojamientos publicados.</small></div>`}</div>`}
function choose(x){s.dest=x;s.sug=false;s.cal=false;s.g=false;home();setTimeout(()=>{let e=document.getElementById('dest');if(e)e.value=x},0)}
function cal(){s.cal=!s.cal;s.g=false;s.sug=false;home()} function guest(){s.g=!s.g;s.cal=false;s.sug=false;home()}
function calendar(){let ny=s.m==11?s.y+1:s.y,nm=(s.m+1)%12;return `<div class="calendar"><div class="calhead"><button onclick="event.stopPropagation();move(-1)">‹</button><b>Selecciona entrada y salida</b><button onclick="event.stopPropagation();move(1)">›</button></div><div class="months">${month(s.y,s.m)}${month(ny,nm)}</div></div>`}
function month(y,m){let N=['Enero','Febrero','Marzo','Abril','Mayo','Junio','Julio','Agosto','Septiembre','Octubre','Noviembre','Diciembre'],f=new Date(y,m,1).getDay(),n=new Date(y,m+1,0).getDate(),c='';for(let i=0;i<f;i++)c+='<span></span>';for(let d=1;d<=n;d++){let q=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,z=q==s.a||q==s.b?' sel':s.a&&s.b&&q>s.a&&q<s.b?' range':'';c+=`<span class="day${z}" onclick="event.stopPropagation();pick('${q}')">${d}</span>`}return `<div class="month"><h3 style="text-align:center">${N[m]} ${y}</h3><div class="week">${['D','L','M','M','J','V','S'].map(x=>`<span>${x}</span>`).join('')}</div><div class="days">${c}</div></div>`}
function pick(q){if(!s.a||s.b){s.a=q;s.b=null}else if(q>s.a){s.b=q;s.cal=false}else{s.a=q;s.b=null}home()}function move(n){s.m+=n;if(s.m<0){s.m=11;s.y--}if(s.m>11){s.m=0;s.y++}home()}
function guestbox(){return `<div class="guestpop"><b>Huéspedes</b>${counter('Adultos','ad')}${counter('Niños','ni')}<button style="width:100%" onclick="s.g=false;home()">Listo</button></div>`}function counter(n,k){return `<div class="grow"><span>${n}</span><div class="counter"><button onclick="cnt('${k}',-1)">−</button><b>${s[k]}</b><button onclick="cnt('${k}',1)">+</button></div></div>`}function cnt(k,n){s[k]=Math.max(k=='ad'?1:0,s[k]+n);home()}
function search(){let e=document.getElementById('dest');if(e)s.dest=e.value;let r=availableListings().filter(x=>(!s.dest||x.commune.toLowerCase()==s.dest.toLowerCase()) && x.cap>=s.ad+s.ni && (!s.a||!s.b||!overlaps(x.id,s.a,s.b)));A.innerHTML=`<section class="results"><span class="back" onclick="home()">← Modificar búsqueda</span><h1>${s.dest?'Alojamientos en '+s.dest:'Todos los alojamientos'}</h1><p class="muted">${r.length} resultado(s) · ${fmt(s.a)} → ${fmt(s.b)} · ${s.ad+s.ni} huésped(es)</p>${r.length?r.map(x=>`<div class="result clickable" onclick="detail(${x.id})"><img src="${(x.photos&&x.photos.length?x.photos[0]:x.img)}"><div class="resultbody"><h3>${x.name}</h3><p>${x.commune}, ${x.region} · ${x.type||'Alojamiento'} · hasta ${x.cap} huéspedes</p><div class="mini-amenities">${amenityList(x).slice(0,3).map(a=>`<span>✓ ${a}</span>`).join('')}</div><small class="openhint">Ver alojamiento →</small></div><div class="resultprice"><span class="price">${money(x.price)} / noche</span>${s.a&&s.b?`<small>Disponible para tus fechas</small>`:''}</div></div>`).join(''):'<div class="box"><h3>No hay alojamientos publicados en este destino.</h3><p class="muted">Prueba seleccionando uno de los destinos sugeridos por Finde.</p></div>'}</section>`;scrollTo(0,0)}
function showAll(){s.dest='';search()}
let ownerProfile=JSON.parse(localStorage.getItem('findeOwnerProfile')||'null')||{name:'Carolina',docType:'RUT',docNumber:''};
function saveOwnerProfile(){let t=document.getElementById('ownerDocType').value,n=document.getElementById('ownerDoc').value.trim();if(!validDocument(t,n)){alert(t==='RUT'?'Ingresa un RUT chileno válido.':'Ingresa un número de documento válido.');return}ownerProfile.docType=t;ownerProfile.docNumber=n;localStorage.setItem('findeOwnerProfile',JSON.stringify(ownerProfile));alert('Identificación guardada en la demo.');dashboard()}
function ownerLogin(){A.innerHTML=`<section class="login"><span class="back" onclick="home()">← Volver a Finde</span><h1>Acceso propietarios</h1><label>Correo</label><input value="propietario@demo.cl"><label>Contraseña</label><input type="password" value="123456"><button style="width:100%" onclick="dashboard()">Ingresar a la demo</button><p class="muted">Demo local: los alojamientos nuevos se guardan en este navegador.</p></section>`;scrollTo(0,0)}
function ownerNav(){return `<aside class="sidebar"><h2>Finde</h2><p>Portal propietario</p><button onclick="dashboard()">Resumen</button><button onclick="properties()">Alojamientos</button><button onclick="ownerReservations()">Reservas</button><button onclick="ownerCalendar()">Calendario</button><button onclick="ownerIncome()">Ingresos</button><button onclick="home()">Salir</button></aside>`}
function dashboard(){let confirmed=reservations.filter(r=>r.status==='Confirmada'),income=confirmed.reduce((a,r)=>a+r.total,0);A.innerHTML=`<section class="panel"><div class="dash">${ownerNav()}<div><h1>Hola, Carolina</h1><p class="muted">Administra tus alojamientos y las reservas que llegan desde Finde.</p><div class="stats"><div class="stat">Reservas<b>${confirmed.length}</b></div><div class="stat">Ingresos brutos<b>${money(income)}</b></div><div class="stat">Próximas llegadas<b>${confirmed.filter(r=>r.checkin>=new Date().toISOString().slice(0,10)).length}</b></div><div class="stat">Alojamientos<b>${listings.length}</b></div></div><div class="box"><h2>Últimas reservas</h2>${confirmed.length?confirmed.slice().reverse().slice(0,4).map(reservationRow).join(''):'<p class="muted">Todavía no hay reservas confirmadas. Haz una desde el flujo turista para probar la conexión.</p>'}</div><div class="box"><h2>Identificación del propietario</h2><p class="muted">Estos datos son privados y quedan disponibles para Administración Finde.</p><div class="block-grid"><label>Tipo de documento<select id="ownerDocType"><option ${ownerProfile.docType==='RUT'?'selected':''}>RUT</option><option ${ownerProfile.docType==='DNI'?'selected':''}>DNI</option><option ${ownerProfile.docType==='Pasaporte'?'selected':''}>Pasaporte</option></select></label><label>Número de documento<input id="ownerDoc" value="${ownerProfile.docNumber||''}" placeholder="Documento"></label><button onclick="saveOwnerProfile()">Guardar identificación</button></div></div></div></div></section>`;scrollTo(0,0)}
function properties(){A.innerHTML=`<section class="panel"><span class="back" onclick="dashboard()">← Volver al panel</span><h1>Mis alojamientos</h1><button onclick="addForm()">+ Agregar alojamiento</button><div class="box">${listings.map(x=>`<div class="row"><span><b>${x.name}</b><br><small class="muted">${x.commune}, ${x.region} · ${money(x.price)}/noche · ${photoList(x).length} foto(s)</small></span><div class="listing-actions"><span class="tag ${x.active===false?'offtag':''}">${x.active===false?'Pausado':'Publicado'}</span><button class="secondary" onclick="toggleListing(${x.id})">${x.active===false?'Activar':'Pausar'}</button><button class="secondary" onclick="editListing(${x.id})">Editar</button><button class="secondary" onclick="managePhotos(${x.id})">Fotos (${photoList(x).length}/5)</button><button class="danger" onclick="askDelete(${x.id})">Eliminar</button></div></div>`).join('')}</div></section>`;scrollTo(0,0)}

function toggleListing(id){let x=listings.find(v=>v.id==id);if(!x)return;x.active=x.active===false?true:false;save();properties()}
function photoList(x){return (x.photos&&x.photos.length?x.photos:(x.img?[x.img]:[])).slice(0,5)}

function editListing(id){
 let x=listings.find(v=>v.id==id); if(!x)return;
 let services=['Wifi','Estacionamiento','Cocina','Calefacción','Desayuno','Piscina','Parrilla','Mascotas'];
 A.innerHTML=`<section class="form wideform"><span class="back" onclick="properties()">← Mis alojamientos</span><h1>Editar alojamiento</h1><label>Nombre</label><input id="en" value="${esc(x.name)}"><div class="two"><div><label>Tipo</label><select id="etype">${['Cabaña','Hotel','Hostal','Departamento','Casa','Otro'].map(v=>`<option ${v==(x.type||'Cabaña')?'selected':''}>${v}</option>`).join('')}</select></div><div><label>Capacidad máxima</label><input id="ecap" type="number" value="${x.cap||2}"></div></div><div class="two"><div><label>Comuna</label><input id="ec" value="${esc(x.commune)}"></div><div><label>Región</label><input id="er" value="${esc(x.region)}"></div></div><div class="three"><div><label>Precio/noche</label><input id="ep" type="number" value="${x.price}"></div><div><label>Habitaciones</label><input id="ebedrooms" type="number" value="${x.bedrooms||1}"></div><div><label>Camas</label><input id="ebeds" type="number" value="${x.beds||1}"></div></div><label>Descripción</label><textarea id="ed">${esc(x.description||'')}</textarea><label>Servicios</label><div class="checks">${services.map(v=>`<label><input type="checkbox" name="esvc" value="${v}" ${amenityList(x).includes(v)?'checked':''}> ${v}</label>`).join('')}</div><div class="two"><div><label>Check-in</label><input id="echeckin" type="time" value="${x.checkin||'15:00'}"></div><div><label>Check-out</label><input id="echeckout" type="time" value="${x.checkout||'11:00'}"></div></div><label>Política de cancelación</label><select id="ecancel">${['Cancelación flexible hasta 48 horas antes.','Cancelación moderada hasta 5 días antes.','No reembolsable.'].map(v=>`<option ${v==(x.cancel||'Cancelación flexible hasta 48 horas antes.')?'selected':''}>${v}</option>`).join('')}</select><button style="width:100%" onclick="saveEdit(${id})">Guardar cambios</button></section>`;scrollTo(0,0)
}
function esc(v){return String(v??'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;')}
function saveEdit(id){
 let x=listings.find(v=>v.id==id); if(!x)return;
 let n=document.getElementById('en').value.trim(),c=document.getElementById('ec').value.trim(),r=document.getElementById('er').value.trim(),p=+document.getElementById('ep').value,cap=+document.getElementById('ecap').value;
 if(!n||!c||!r||!p||!cap){alert('Completa nombre, comuna, región, precio y capacidad.');return}
 Object.assign(x,{name:n,commune:c,region:r,price:p,cap,type:document.getElementById('etype').value,bedrooms:+document.getElementById('ebedrooms').value,beds:+document.getElementById('ebeds').value,description:document.getElementById('ed').value.trim(),services:[...document.querySelectorAll('input[name="esvc"]:checked')].map(e=>e.value),checkin:document.getElementById('echeckin').value,checkout:document.getElementById('echeckout').value,cancel:document.getElementById('ecancel').value});
 save();properties()
}

let managePhotoId=null, managedPhotos=[];
function managePhotos(id){
 let x=listings.find(v=>v.id==id); if(!x)return;
 managePhotoId=id;managedPhotos=[...photoList(x)];
 A.innerHTML=`<section class="form"><span class="back" onclick="properties()">← Mis alojamientos</span><h1>Fotos de ${x.name}</h1><p class="muted">Puedes tener hasta 5 fotos JPG/JPEG. La primera es la portada que verá el turista.</p><div class="photo-upload"><input id="morePhotos" type="file" accept=".jpg,.jpeg,image/jpeg" multiple onchange="addManagedPhotos(this.files)"><label for="morePhotos">📷 Agregar fotos JPG</label></div><div id="managedPreviews" class="previews"></div><button style="width:100%" onclick="saveManagedPhotos()">Guardar fotos</button></section>`;renderManagedPhotos();scrollTo(0,0)
}
function renderManagedPhotos(){
 let e=document.getElementById('managedPreviews');if(!e)return;
 e.innerHTML=managedPhotos.map((p,i)=>`<div class="preview"><img src="${p}"><button onclick="removeManagedPhoto(${i})">×</button>${i===0?'<span class="cover">Portada</span>':''}</div>`).join('')
}
function addManagedPhotos(files){
 let arr=[...files]; if(arr.length>5){alert('Puedes subir un máximo de 5 fotos por alojamiento.');arr=arr.slice(0,5)}
 if(managedPhotos.length+arr.length>5){alert('Cada alojamiento puede tener un máximo de 5 fotos.');arr=arr.slice(0,Math.max(0,5-managedPhotos.length))}
 if(arr.some(f=>f.type!=='image/jpeg')){alert('Solo se permiten archivos JPG o JPEG.');return}
 arr.forEach(f=>{let r=new FileReader();r.onload=e=>{managedPhotos.push(e.target.result);renderManagedPhotos()};r.readAsDataURL(f)})
}
function removeManagedPhoto(i){
 if(managedPhotos.length<=1){alert('El alojamiento debe conservar al menos una foto.');return}
 managedPhotos.splice(i,1);renderManagedPhotos()
}
function saveManagedPhotos(){
 let x=listings.find(v=>v.id==managePhotoId);if(!x)return;
 x.photos=[...managedPhotos];x.img=managedPhotos[0];
 try{save();properties()}catch(e){alert('Las fotos son demasiado pesadas para esta demo. Prueba con JPG más livianos.')}
}

function askDelete(id){
 let x=listings.find(v=>v.id==id);if(!x)return;
 A.insertAdjacentHTML('beforeend',`<div class="modalback" id="deleteModal"><div class="modal"><h2>¿Eliminar alojamiento?</h2><p>¿Estás seguro de que quieres eliminar <b>${x.name}</b>?</p><p class="muted">Dejará de aparecer inmediatamente en las búsquedas de turistas.</p><div class="modalactions"><button class="secondary" onclick="closeDelete()">Cancelar</button><button class="danger big" onclick="confirmDelete(${id})">Sí, eliminar alojamiento</button></div></div></div>`)
}
function closeDelete(){document.getElementById('deleteModal')?.remove()}
function confirmDelete(id){listings=listings.filter(v=>v.id!=id);save();closeDelete();properties()}

function addForm(){pendingPhotos=[];A.innerHTML=`<section class="form wideform"><span class="back" onclick="properties()">← Mis alojamientos</span><h1>Agregar alojamiento</h1><p class="muted">Completa la información que necesita un turista para decidir y reservar.</p><label>Nombre del alojamiento</label><input id="n" placeholder="Ej: Cabañas Los Aromos"><div class="two"><div><label>Tipo de alojamiento</label><select id="type"><option>Cabaña</option><option>Hotel</option><option>Hostal</option><option>Departamento</option><option>Casa</option><option>Otro</option></select></div><div><label>Capacidad máxima</label><input id="cap" type="number" min="1" value="4"></div></div><div class="two"><div><label>Comuna</label><input id="c" placeholder="Ej: Cochamó"></div><div><label>Región</label><input id="r" placeholder="Ej: Los Lagos"></div></div><div class="three"><div><label>Precio por noche</label><input id="p" type="number" min="1" placeholder="75000"></div><div><label>Habitaciones</label><input id="bedrooms" type="number" min="0" value="1"></div><div><label>Camas</label><input id="beds" type="number" min="1" value="2"></div></div><label>Descripción</label><textarea id="desc" placeholder="Explica qué hace atractivo el alojamiento, entorno y características principales."></textarea><label>Servicios</label><div class="checks">${['Wifi','Estacionamiento','Cocina','Calefacción','Desayuno','Piscina','Parrilla','Mascotas'].map(v=>`<label><input type="checkbox" name="svc" value="${v}"> ${v}</label>`).join('')}</div><div class="two"><div><label>Check-in</label><input id="checkin" type="time" value="15:00"></div><div><label>Check-out</label><input id="checkout" type="time" value="11:00"></div></div><label>Política de cancelación</label><select id="cancel"><option>Cancelación flexible hasta 48 horas antes.</option><option>Cancelación moderada hasta 5 días antes.</option><option>No reembolsable.</option></select><label>Fotos del alojamiento</label><div class="photo-upload"><input id="photos" type="file" accept=".jpg,.jpeg,image/jpeg" multiple onchange="loadPhotos(this.files)"><label for="photos">📷 Seleccionar fotos JPG</label><p class="muted">Máximo 5. La primera será la portada.</p></div><div id="previews" class="previews"></div><button style="width:100%" onclick="publish()">Publicar alojamiento</button></section>`;scrollTo(0,0)}
function loadPhotos(files){
 let arr=[...files]; if(arr.length>5){alert('Puedes subir un máximo de 5 fotos.');arr=arr.slice(0,5)}
 let bad=arr.filter(f=>!['image/jpeg','image/jpg'].includes(f.type));
 if(bad.length){alert('En esta demo solo puedes subir archivos JPG o JPEG.');return}
 pendingPhotos=[];
 if(!arr.length){renderPhotos();return}
 let done=0;
 arr.forEach(f=>{
   let reader=new FileReader();
   reader.onload=e=>{pendingPhotos.push(e.target.result);done++;if(done===arr.length)renderPhotos()};
   reader.readAsDataURL(f)
 });
}
function renderPhotos(){
 let el=document.getElementById('previews');if(!el)return;
 el.innerHTML=pendingPhotos.map((p,i)=>`<div class="preview"><img src="${p}"><button onclick="removePhoto(${i})">×</button>${i===0?'<span class="cover">Portada</span>':''}</div>`).join('');
}
function removePhoto(i){pendingPhotos.splice(i,1);renderPhotos()}
function publish(){
 let n=document.getElementById('n').value.trim(),c=document.getElementById('c').value.trim(),r=document.getElementById('r').value.trim(),p=+document.getElementById('p').value,cap=+document.getElementById('cap').value,desc=document.getElementById('desc').value.trim();
 if(!n||!c||!r||!p||!cap){alert('Completa nombre, comuna, región, precio y capacidad.');return}
 if(!pendingPhotos.length){alert('Selecciona al menos una foto JPG del alojamiento.');return}
 let item={id:Date.now(),name:n,commune:c,region:r,price:p,cap,type:document.getElementById('type').value,bedrooms:+document.getElementById('bedrooms').value,beds:+document.getElementById('beds').value,services:[...document.querySelectorAll('input[name="svc"]:checked')].map(e=>e.value),checkin:document.getElementById('checkin').value,checkout:document.getElementById('checkout').value,cancel:document.getElementById('cancel').value,photos:[...pendingPhotos],img:pendingPhotos[0],description:desc,active:true};
 try{listings.push(item);save()}catch(e){listings.pop();alert('Las fotos son demasiado pesadas para esta demo. Prueba con JPG más livianos.');return}
 pendingPhotos=[];
 A.innerHTML=`<section class="form"><div class="success"><h2>✓ Alojamiento publicado</h2><p><b>${n}</b> ya está visible para turistas que busquen ${c}.</p></div><button onclick="s.dest='${c}';home()">Ver como turista</button> <button class="outline" onclick="properties()">Volver a mis alojamientos</button></section>`;scrollTo(0,0)
}

function detail(id){
 let x=listings.find(v=>v.id==id);if(!x)return;
 let ps=photoList(x), nights=(s.a&&s.b)?Math.max(1,Math.round((new Date(s.b+'T12:00')-new Date(s.a+'T12:00'))/86400000)):0,total=nights*x.price;
 A.innerHTML=`<section class="detailpage"><span class="back" onclick="search()">← Volver a resultados</span><div class="detailtitle"><div><h1>${x.name}</h1><p class="muted">📍 ${x.commune}, ${x.region} · ${x.type||'Alojamiento'}</p></div><span class="trust">✓ Alojamiento publicado en Finde</span></div><div class="detailgallery">${ps.map((p,i)=>`<img class="${i===0?'mainphoto':''}" src="${p}">`).join('')}</div><div class="detailgrid"><div><h2>Sobre este alojamiento</h2><p>${x.description||'Alojamiento publicado en Finde.'}</p><div class="facts"><div><b>${x.cap}</b><span>huéspedes</span></div><div><b>${x.bedrooms||1}</b><span>habitaciones</span></div><div><b>${x.beds||1}</b><span>camas</span></div></div><h2>Servicios</h2><div class="amenities">${amenityList(x).map(a=>`<span>✓ ${a}</span>`).join('')}</div><h2>Información de la estadía</h2><p><b>Check-in:</b> desde ${x.checkin||'15:00'} · <b>Check-out:</b> hasta ${x.checkout||'11:00'}</p><p><b>Cancelación:</b> ${x.cancel||'Consulta las condiciones antes de reservar.'}</p><h2>Ubicación</h2><div class="mapmock">📍 ${x.commune}, ${x.region}<small>La ubicación exacta se entregará con la confirmación de la reserva.</small></div></div><aside class="bookingbox"><div class="price">${money(x.price)} / noche</div><p class="muted">Comprueba disponibilidad y precio total.</p><label>Entrada</label><input type="date" id="din" value="${s.a||''}"><label>Salida</label><input type="date" id="dout" value="${s.b||''}"><label>Huéspedes</label><input type="number" id="dguests" min="1" max="${x.cap}" value="${Math.min(s.ad+s.ni,x.cap)}"><button onclick="calcDetail(${id})">Comprobar disponibilidad</button><div id="calc">${nights?`<p>${nights} noche(s) × ${money(x.price)}</p><h3>Total estadía: ${money(total)}</h3><small>Sin cobro en esta maqueta.</small><button onclick="reserveDemo(${id})">Reservar</button>`:'<p class="muted">Selecciona fechas para calcular el total.</p>'}</div></aside></div></section>`;scrollTo(0,0)
}
function calcDetail(id){
 let x=listings.find(v=>v.id==id),a=document.getElementById('din').value,b=document.getElementById('dout').value,g=+document.getElementById('dguests').value;
 if(!a||!b||b<=a){alert('Selecciona una fecha de salida posterior a la entrada.');return}
 if(g<1||g>x.cap){alert(`Este alojamiento admite hasta ${x.cap} huéspedes.`);return}
 if(overlaps(id,a,b)){alert('Este alojamiento ya está reservado en esas fechas. Prueba otras.');return}
 s.a=a;s.b=b;s.ad=g;s.ni=0;
 let nights=Math.round((new Date(b+'T12:00')-new Date(a+'T12:00'))/86400000),total=nights*x.price;
 document.getElementById('calc').innerHTML=`<p>${nights} noche(s) × ${money(x.price)}</p><h3>Total estadía: ${money(total)}</h3><small>Disponible para estas fechas</small><button onclick="reserveDemo(${id})">Reservar</button>`
}
function reserveDemo(id){
 let x=listings.find(v=>v.id==id);if(!x)return;
 if(!s.a||!s.b){alert('Selecciona las fechas antes de reservar.');return}
 if(overlaps(id,s.a,s.b)){alert('Esas fechas ya están reservadas. Elige otras fechas.');return}
 let nights=Math.round((new Date(s.b+'T12:00')-new Date(s.a+'T12:00'))/86400000),total=nights*x.price;
 A.innerHTML=`<section class="form"><span class="back" onclick="detail(${id})">← Volver al alojamiento</span><h1>Completa tu reserva</h1><div class="booking-summary"><b>${x.name}</b><p>${x.commune}, ${x.region}</p><p>${fmt(s.a)} → ${fmt(s.b)} · ${nights} noche(s) · ${s.ad+s.ni} huésped(es)</p><h3>Total: ${money(total)}</h3></div><label>Nombre y apellido</label><input id="guestName" placeholder="Ej: María González"><label>Tipo de documento</label><select id="guestDocType"><option>RUT</option><option>DNI</option><option>Pasaporte</option></select><label>Número de documento</label><input id="guestDoc" placeholder="Ej: 12.345.678-5"><label>Correo electrónico</label><input id="guestEmail" type="email" placeholder="maria@correo.cl"><label>Teléfono</label><input id="guestPhone" placeholder="+56 9 ..."><label class="terms"><input id="terms" type="checkbox"> He revisado las fechas, el precio y las condiciones de cancelación.</label><button style="width:100%" onclick="confirmBooking(${id})">Confirmar reserva</button><p class="muted">Demo: todavía no se realiza ningún cobro real.</p></section>`;scrollTo(0,0)
}
function confirmBooking(id){
 let x=listings.find(v=>v.id==id),name=document.getElementById('guestName').value.trim(),email=document.getElementById('guestEmail').value.trim(),phone=document.getElementById('guestPhone').value.trim(),docType=document.getElementById('guestDocType').value,docNumber=document.getElementById('guestDoc').value.trim();
 if(!name||!email||!phone||!docNumber){alert('Completa nombre, documento, correo y teléfono.');return} if(!validDocument(docType,docNumber)){alert(docType==='RUT'?'Ingresa un RUT chileno válido.':'Ingresa un número de documento válido.');return} if(!validEmail(email)){alert('Ingresa un correo válido.');return} if(!document.getElementById('terms').checked){alert('Confirma que revisaste los datos y condiciones.');return}
 if(overlaps(id,s.a,s.b)){alert('Mientras completabas la reserva, esas fechas dejaron de estar disponibles.');detail(id);return}
 let nights=Math.round((new Date(s.b+'T12:00')-new Date(s.a+'T12:00'))/86400000);
 let r={id:Date.now(),listingId:id,listingName:x.name,guest:name,email,phone,docType,docNumber,checkin:s.a,checkout:s.b,guests:s.ad+s.ni,nights,total:nights*x.price,status:'Confirmada',created:new Date().toISOString()};
 reservations.push(r);saveReservations();
 A.innerHTML=`<section class="form"><div class="success"><div class="findito-celebration"><img src="findito.png" alt="Findito celebrando"><div><span class="findito-label">FINDITO CELEBRA CONTIGO</span><h2>✓ Reserva confirmada</h2></div></div><p class="confirmation-code">Código ${bookingCode(r.id)}</p><p><b>${name}</b>, tu reserva en <b>${x.name}</b> quedó registrada.</p><p>${fmt(r.checkin)} → ${fmt(r.checkout)} · ${r.nights} noche(s) · ${r.guests} huésped(es)</p><h3>Total: ${money(r.total)}</h3><p>La reserva ya aparece al propietario y las fechas quedaron bloqueadas. En la plataforma real, aquí enviaremos también la confirmación por correo y el comprobante de pago.</p></div><button onclick="home()">Volver al inicio</button> <button class="outline" onclick="ownerLogin()">Comprobar como propietario</button></section>`;scrollTo(0,0)
}
function reservationRow(r){return `<div class="row"><span><b>${r.guest}</b><br><small class="muted">${r.listingName} · ${fmt(r.checkin)} → ${fmt(r.checkout)} · ${r.guests} huésped(es)</small></span><span class="reservation-actions"><b>${money(r.total)}</b><br><span class="tag">${r.status}</span><button class="tiny secondary" onclick="reservationDetail(${r.id})">Ver detalle</button></span></div>`}
function reservationDetail(id){
 let r=reservations.find(v=>v.id==id);if(!r)return;
 let displayName=(r.guest||'Huésped').split(' ');displayName=displayName[0]+(displayName[1]?' '+displayName[1][0]+'.':'');
 A.innerHTML=`<section class="form"><span class="back" onclick="ownerReservations()">← Reservas</span><h1>Detalle de reserva</h1><div class="booking-summary"><b>${r.listingName}</b><p>Código: ${bookingCode(r.id)}</p><p>${fmt(r.checkin)} → ${fmt(r.checkout)} · ${r.nights} noche(s)</p><h3>${money(r.total)}</h3></div><h3>Huésped</h3><p><b>${displayName}</b><br>${r.guests} huésped(es)</p><div class="privacy-note"><b>Datos protegidos por Finde</b><p>El correo y teléfono del huésped son administrados por Finde y no se muestran al propietario.</p></div><p><span class="tag">${r.status}</span></p></section>`;scrollTo(0,0)
}
function ownerReservations(){A.innerHTML=`<section class="panel"><div class="dash">${ownerNav()}<div><h1>Reservas</h1><p class="muted">Reservas creadas desde el flujo turista.</p><div class="box">${reservations.length?reservations.slice().reverse().map(reservationRow).join(''):'<p class="muted">No hay reservas todavía.</p>'}</div></div></div></section>`;scrollTo(0,0)}
function ownerCalendar(){
 let rs=reservations.filter(r=>r.status==='Confirmada').slice().sort((a,b)=>a.checkin.localeCompare(b.checkin));
 A.innerHTML=`<section class="panel"><div class="dash">${ownerNav()}<div><h1>Calendario y disponibilidad</h1><p class="muted">Las reservas Finde se bloquean automáticamente. También puedes bloquear fechas ocupadas por otros motivos.</p>
 <div class="box owner-block-form"><h2>Bloquear fechas manualmente</h2><div class="block-grid"><label>Alojamiento<select id="blockListing">${listings.map(x=>`<option value="${x.id}">${x.name}</option>`).join('')}</select></label><label>Desde<input type="date" id="blockFrom"></label><label>Hasta<input type="date" id="blockTo"></label><button onclick="addOwnerBlock()">Bloquear fechas</button></div><p class="muted">Estas fechas dejarán de estar disponibles inmediatamente en la búsqueda pública.</p></div>
 <div class="box"><h2>Reservas Finde</h2>${rs.length?rs.map(r=>`<div class="calendar-booking"><b>${r.listingName}</b><span>${fmt(r.checkin)} → ${fmt(r.checkout)}</span><span>${r.guest.split(' ')[0]}</span><span class="tag">Reservado por Finde</span></div>`).join(''):'<p class="muted">No hay reservas confirmadas.</p>'}</div>
 <div class="box"><h2>Bloqueos del propietario</h2>${ownerBlocks.length?ownerBlocks.slice().sort((a,b)=>a.checkin.localeCompare(b.checkin)).map(v=>`<div class="calendar-booking"><b>${v.listingName}</b><span>${fmt(v.checkin)} → ${fmt(v.checkout)}</span><span>Bloqueo manual</span><span><button class="tiny danger" onclick="removeOwnerBlock(${v.id})">Desbloquear</button></span></div>`).join(''):'<p class="muted">No has bloqueado fechas manualmente.</p>'}</div>
 </div></div></section>`;scrollTo(0,0)
}
function addOwnerBlock(){
 let listingId=Number(document.getElementById('blockListing').value),a=document.getElementById('blockFrom').value,b=document.getElementById('blockTo').value,x=listings.find(v=>v.id==listingId);
 if(!a||!b){alert('Selecciona fecha desde y hasta.');return}
 if(b<=a){alert('La fecha final debe ser posterior a la inicial.');return}
 if(reservations.some(r=>r.listingId==listingId&&r.status==='Confirmada'&&a<r.checkout&&b>r.checkin)){alert('Ese período ya contiene una reserva confirmada por Finde.');return}
 if(manualOverlap(listingId,a,b)){alert('Ese período ya está bloqueado.');return}
 ownerBlocks.push({id:Date.now(),listingId,listingName:x.name,checkin:a,checkout:b});saveOwnerBlocks();ownerCalendar()
}
function removeOwnerBlock(id){ownerBlocks=ownerBlocks.filter(v=>v.id!=id);saveOwnerBlocks();ownerCalendar()}

function ownerIncome(){let rs=reservations.filter(r=>r.status==='Confirmada'),gross=rs.reduce((a,r)=>a+r.total,0),fee=Math.round(gross*.10),net=gross-fee;A.innerHTML=`<section class="panel"><div class="dash">${ownerNav()}<div><h1>Ingresos</h1><p class="muted">Cálculo demostrativo. La comisión todavía no representa un cobro real.</p><div class="stats"><div class="stat">Reservas<b>${rs.length}</b></div><div class="stat">Ventas<b>${money(gross)}</b></div><div class="stat">Comisión demo 10%<b>${money(fee)}</b></div><div class="stat">A recibir<b>${money(net)}</b></div></div><div class="box"><h2>Movimientos</h2>${rs.length?rs.slice().reverse().map(r=>`<div class="row"><span><b>${r.listingName}</b><br><small class="muted">${r.guest} · ${fmt(r.checkin)}</small></span><span><b>${money(r.total)}</b><br><small class="muted">Neto demo ${money(Math.round(r.total*.9))}</small></span></div>`).join(''):'<p class="muted">Aún no hay movimientos.</p>'}</div></div></div></section>`;scrollTo(0,0)}


/* ===== V13 CENTRO DE CONTROL ADMINISTRADOR FINDE ===== */
let adminPaymentState=JSON.parse(localStorage.getItem('findeAdminPayments')||'{}');
let adminIssues=JSON.parse(localStorage.getItem('findeAdminIssues')||'null')||[{id:'INC-001',type:'Reserva',subject:'Ejemplo de incidencia de soporte',status:'Abierta',reservation:'Sin asociar',notes:'Caso demostrativo.'}];
function saveAdmin(){localStorage.setItem('findeAdminPayments',JSON.stringify(adminPaymentState));localStorage.setItem('findeAdminIssues',JSON.stringify(adminIssues))}
function paymentStatus(id){return adminPaymentState[id]||'Pendiente transferencia'}
function setPaymentStatus(id,status){adminPaymentState[id]=status;saveAdmin();adminPayments()}
function setReservationStatus(id,status){let r=reservations.find(x=>x.id==id);if(!r)return;r.status=status;saveReservations();adminReservationDetail(id)}
function setListingReview(id,status){let x=listings.find(v=>v.id==id);if(!x)return;x.adminStatus=status;if(status==='Aprobado')x.active=true;if(status==='Rechazado'||status==='Pausado')x.active=false;save();adminListings()}
function adminStatus(x){return x.adminStatus||(x.active===false?'Pausado':'Aprobado')}
function adminLogin(){A.innerHTML=`<section class="login admin-login"><span class="back" onclick="home()">← Volver a Finde</span><div class="admin-badge">Administración Finde</div><h1>Centro de control</h1><p class="muted">Gestiona la operación completa de Finde.</p><label>Correo administrador</label><input value="admin@finde.cl"><label>Contraseña</label><input type="password" value="123456"><button style="width:100%" onclick="adminDashboard()">Ingresar a la demo</button><p class="muted">Acceso demostrativo. La autenticación real se implementará con el backend.</p></section>`;scrollTo(0,0)}
function adminNav(active='Resumen'){let items=[['Resumen','adminDashboard()'],['Alojamientos','adminListings()'],['Experiencias','adminExperienceReservations()'],['Propietarios','adminOwners()'],['Reservas','adminReservations()'],['Clientes','adminCustomers()'],['Pagos','adminPayments()'],['Calendario','adminCalendar()'],['Reportes','adminReports()'],['Configuración','adminSettings()'],['Incidencias','adminIncidents()']];return `<aside class="admin-sidebar"><div class="admin-logo">Finde <small>ADMIN</small></div>${items.map(i=>`<button class="${active==i[0]?'active':''}" onclick="${i[1]}">${i[0]}</button>`).join('')}<button onclick="home()">Salir</button></aside>`}
function adminShell(active,title,subtitle,content){A.innerHTML=`<section class="admin-panel"><div class="admin-layout">${adminNav(active)}<div class="admin-content"><div class="admin-head"><div><small>PANEL FINDE</small><h1>${title}</h1><p class="muted">${subtitle}</p></div><button class="outline" onclick="home()">Ver sitio público</button></div>${content}</div></div></section>`;scrollTo(0,0)}
function adminMetrics(){let rs=reservations.filter(r=>r.status!=='Cancelada'&&r.status!=='Reembolsada'),gross=rs.reduce((a,r)=>a+r.total,0),fee=Math.round(gross*.10),active=availableListings().length,paid=rs.filter(r=>paymentStatus(r.id)==='Transferido').reduce((a,r)=>a+Math.round(r.total*.9),0);return {rs,gross,fee,net:gross-fee,active,paid,pendingPay:gross-fee-paid}}
function adminDashboard(){let m=adminMetrics(),pending=listings.filter(x=>adminStatus(x)==='Pendiente').length,open=adminIssues.filter(x=>x.status==='Abierta').length;adminShell('Resumen','Resumen','Estado general de la operación de Finde.',`<div class="admin-kpis"><div><small>Reservas</small><b>${m.rs.length}</b><span>activas</span></div><div><small>Ventas</small><b>${money(m.gross)}</b><span>volumen reservado</span></div><div><small>Comisión Finde</small><b>${money(m.fee)}</b><span>demo 10%</span></div><div><small>Por pagar</small><b>${money(m.pendingPay)}</b><span>a propietarios</span></div><div><small>Alojamientos</small><b>${m.active}</b><span>activos</span></div></div><div class="admin-grid"><div class="admin-card"><h2>Reservas recientes</h2>${m.rs.length?m.rs.slice().reverse().slice(0,5).map(reservationRow).join(''):'<p class="muted">Aún no hay reservas.</p>'}</div><div class="admin-card"><h2>Pendientes</h2><div class="task"><b>${pending}</b><span>Alojamientos por revisar</span></div><div class="task"><b>${m.rs.filter(r=>paymentStatus(r.id)!=='Transferido').length}</b><span>Pagos a propietarios</span></div><div class="task"><b>${open}</b><span>Incidencias abiertas</span></div></div></div>`)}
function adminListings(){adminShell('Alojamientos','Alojamientos','Revisa, aprueba, pausa o rechaza la oferta de Finde.',`<div class="admin-card"><div class="admin-toolbar"><input id="adminListingSearch" placeholder="Buscar alojamiento o comuna" oninput="adminListingsFilter()"></div><div id="adminListingRows">${adminListingRows(listings)}</div></div>`)}
function adminListingRows(arr){return arr.map(x=>`<div class="admin-table-row listing-admin"><img src="${photoList(x)[0]||x.img}"><span><b>${x.name}</b><small>${x.commune}, ${x.region} · ${x.type||'Alojamiento'}</small></span><span>${money(x.price)}<small>por noche</small></span><span class="tag ${adminStatus(x)!=='Aprobado'?'offtag':''}">${adminStatus(x)}</span><div class="admin-actions"><button class="tiny secondary" onclick="detail(${x.id})">Ver</button><button class="tiny" onclick="setListingReview(${x.id},'Aprobado')">Aprobar</button><button class="tiny secondary" onclick="setListingReview(${x.id},'Pausado')">Pausar</button><button class="tiny danger" onclick="setListingReview(${x.id},'Rechazado')">Rechazar</button></div></div>`).join('')||'<p class="muted">No hay alojamientos.</p>'}
function adminListingsFilter(){let q=document.getElementById('adminListingSearch').value.toLowerCase(),e=document.getElementById('adminListingRows');e.innerHTML=adminListingRows(listings.filter(x=>(x.name+' '+x.commune+' '+x.region).toLowerCase().includes(q)))}
function adminOwners(){adminShell('Propietarios','Propietarios','Personas y empresas que ofrecen alojamientos en Finde.',`<div class="admin-card"><div class="admin-table-row"><span><b>Carolina Pérez</b><small>propietario@demo.cl · +56 9 5555 5555</small></span><span><b>${listings.length}</b><small>alojamientos</small></span><span><b>${reservations.length}</b><small>reservas</small></span><span class="tag">Activo</span><button class="tiny secondary" onclick="adminOwnerDetail()">Ver ficha</button></div></div>`)}
function adminOwnerDetail(){let gross=reservations.reduce((a,r)=>a+r.total,0);adminShell('Propietarios','Carolina Pérez','Ficha y operación del propietario.',`<div class="admin-grid"><div class="admin-card"><h2>Datos</h2><p><b>Correo:</b> propietario@demo.cl</p><p><b>Teléfono:</b> +56 9 5555 5555</p><p><span class="tag">Activo</span></p></div><div class="admin-card"><h2>Operación</h2><p><b>${listings.length}</b> alojamientos</p><p><b>${reservations.length}</b> reservas</p><p><b>${money(gross)}</b> volumen reservado</p><button onclick="adminListings()">Ver alojamientos</button></div></div>`)}
function adminReservations(){adminShell('Reservas','Reservas','Control de todas las operaciones creadas por turistas.',`<div class="admin-card">${reservations.length?reservations.slice().reverse().map(r=>`<div class="admin-table-row"><span><b>${bookingCode(r.id)}</b><small>${r.guest}</small></span><span><b>${r.listingName}</b><small>${fmt(r.checkin)} → ${fmt(r.checkout)}</small></span><span><b>${money(r.total)}</b><small>${r.guests} huésped(es)</small></span><span class="tag">${r.status}</span><button class="tiny secondary" onclick="adminReservationDetail(${r.id})">Gestionar</button></div>`).join(''):'<p class="muted">Todavía no hay reservas.</p>'}</div>`)}
function adminReservationDetail(id){let r=reservations.find(x=>x.id==id);if(!r)return;adminShell('Reservas','Detalle de reserva',bookingCode(r.id),`<div class="admin-grid"><div class="admin-card"><h2>${r.listingName}</h2><p>${fmt(r.checkin)} → ${fmt(r.checkout)} · ${r.nights} noche(s)</p><p>${r.guests} huésped(es)</p><h2>${money(r.total)}</h2><p><span class="tag">${r.status}</span></p><h3>Cambiar estado</h3><div class="admin-actions"><button class="tiny" onclick="setReservationStatus(${r.id},'Confirmada')">Confirmada</button><button class="tiny secondary" onclick="setReservationStatus(${r.id},'En curso')">En curso</button><button class="tiny secondary" onclick="setReservationStatus(${r.id},'Finalizada')">Finalizada</button><button class="tiny danger" onclick="setReservationStatus(${r.id},'Cancelada')">Cancelada</button></div></div><div class="admin-card"><h2>Cliente</h2><p><b>${r.guest}</b></p><p>${r.email}</p><p>${r.phone}</p><p><b>Documento:</b> ${r.docType||'No registrado'} ${r.docNumber||''}</p><h3>Distribución</h3><p>Comisión Finde: <b>${money(Math.round(r.total*.1))}</b></p><p>Propietario: <b>${money(Math.round(r.total*.9))}</b></p><p>Transferencia: <span class="tag">${paymentStatus(r.id)}</span></p></div></div>`)}
function adminCustomers(){let map={};reservations.forEach(r=>{let k=r.email;if(!map[k])map[k]={name:r.guest,email:r.email,phone:r.phone,count:0,total:0};map[k].count++;map[k].total+=r.total});let cs=Object.values(map);adminShell('Clientes','Clientes','Huéspedes e historial de reservas.',`<div class="admin-card">${cs.length?cs.map(c=>`<div class="admin-table-row"><span><b>${c.name}</b><small>${c.email} · ${c.phone}</small></span><span><b>${c.count}</b><small>reservas</small></span><span><b>${money(c.total)}</b><small>total reservado</small></span><span class="tag">Cliente</span></div>`).join(''):'<p class="muted">Los clientes aparecerán cuando existan reservas.</p>'}</div>`)}
function adminPayments(){let m=adminMetrics();adminShell('Pagos','Pagos','Control de comisión y transferencias a propietarios.',`<div class="admin-kpis"><div><small>Volumen reservas</small><b>${money(m.gross)}</b></div><div><small>Comisión Finde</small><b>${money(m.fee)}</b></div><div><small>Transferido</small><b>${money(m.paid)}</b></div><div><small>Por transferir</small><b>${money(m.pendingPay)}</b></div></div><div class="admin-card"><h2>Operaciones</h2>${m.rs.length?m.rs.map(r=>`<div class="payment-row"><span><b>${bookingCode(r.id)}</b><small>${r.listingName}</small></span><span>Cliente<b>${money(r.total)}</b></span><span>Finde 10%<b>${money(Math.round(r.total*.1))}</b></span><span>Propietario<b>${money(Math.round(r.total*.9))}</b></span><span><span class="tag">${paymentStatus(r.id)}</span>${paymentStatus(r.id)!=='Transferido'?`<button class="tiny" onclick="setPaymentStatus(${r.id},'Transferido')">Marcar transferido</button>`:`<button class="tiny secondary" onclick="setPaymentStatus(${r.id},'Pendiente transferencia')">Reabrir</button>`}</span></div>`).join(''):'<p class="muted">No hay pagos todavía.</p>'}</div>`)}
function adminCalendar(){let rs=reservations.filter(r=>r.status!=='Cancelada').sort((a,b)=>a.checkin.localeCompare(b.checkin));adminShell('Calendario','Calendario general','Reservas y fechas ocupadas de todos los alojamientos.',`<div class="admin-card">${rs.length?rs.map(r=>`<div class="calendar-booking"><b>${r.listingName}</b><span>${fmt(r.checkin)} → ${fmt(r.checkout)}</span><span>${r.guest}</span><span class="tag">${r.status}</span></div>`).join(''):'<p class="muted">No hay fechas ocupadas.</p>'}</div>`)}
function adminReports(){let m=adminMetrics(),nights=m.rs.reduce((a,r)=>a+r.nights,0),avg=m.rs.length?Math.round(m.gross/m.rs.length):0;adminShell('Reportes','Reportes','Indicadores comerciales de Finde.',`<div class="admin-kpis"><div><small>Ventas</small><b>${money(m.gross)}</b></div><div><small>Reservas</small><b>${m.rs.length}</b></div><div><small>Noches</small><b>${nights}</b></div><div><small>Ticket promedio</small><b>${money(avg)}</b></div></div><div class="admin-grid"><div class="admin-card"><h2>Oferta por destino</h2>${destinations().map(d=>`<div class="reportbar"><span>${d.commune}</span><div><i style="width:${Math.min(100,d.count*18)}%"></i></div><b>${d.count}</b></div>`).join('')}</div><div class="admin-card"><h2>Resultado Finde</h2><div class="big-number">${money(m.fee)}</div><p>Comisión demostrativa generada al 10%.</p></div></div>`)}
function adminSettings(){adminShell('Configuración','Configuración','Parámetros generales de la plataforma.',`<div class="admin-grid"><div class="admin-card"><h2>Modelo comercial</h2><label>Comisión Finde (%)</label><input value="10" type="number"><label>Correo de soporte</label><input value="soporte@finde.cl"><button onclick="alert('Configuración guardada en la maqueta.')">Guardar</button></div><div class="admin-card"><h2>Estado de la plataforma</h2><p><span class="tag">Maqueta funcional</span></p><p class="muted">Pagos, correos y autenticación reales se conectarán con el backend.</p></div></div>`)}
function adminIncidents(){adminShell('Incidencias','Incidencias','Problemas de reservas, alojamientos y pagos.',`<div class="admin-card"><button onclick="adminNewIncident()">+ Nueva incidencia</button>${adminIssues.length?adminIssues.slice().reverse().map(i=>`<div class="admin-table-row"><span><b>${i.id}</b><small>${i.type}</small></span><span><b>${i.subject}</b><small>Reserva ${i.reservation}</small></span><span class="tag">${i.status}</span><button class="tiny secondary" onclick="adminIssueDetail('${i.id}')">Gestionar</button></div>`).join(''):'<p class="muted">No hay incidencias.</p>'}</div>`)}
function adminIssueDetail(id){let i=adminIssues.find(x=>x.id===id);if(!i)return;adminShell('Incidencias','Detalle de incidencia',i.id,`<div class="admin-grid"><div class="admin-card"><h2>${i.subject}</h2><p><b>Tipo:</b> ${i.type}</p><p><b>Reserva:</b> ${i.reservation}</p><p><span class="tag">${i.status}</span></p><p>${i.notes||''}</p></div><div class="admin-card"><h2>Gestión</h2>${i.status!=='Resuelta'?`<button onclick="closeIssue('${i.id}')">Marcar resuelta</button>`:''}<button class="secondary" onclick="adminIncidents()">Volver</button></div></div>`)}
function closeIssue(id){let i=adminIssues.find(x=>x.id===id);if(i){i.status='Resuelta';saveAdmin();adminIssueDetail(id)}}
function adminNewIncident(){let subject=prompt('Describe brevemente la incidencia:');if(subject){let rid=prompt('Código de reserva (opcional):')||'Sin asociar';adminIssues.push({id:'INC-'+String(Date.now()).slice(-5),type:'Soporte',subject,status:'Abierta',reservation:rid,notes:'Creada desde el panel administrador.'});saveAdmin();adminIncidents()}}

/* ===== V15 EXPERIENCIAS TURÍSTICAS ===== */
const experienceSeed=[
{id:101,name:'Rafting Río Trancura',commune:'Pucón',region:'Araucanía',category:'Aventura',price:25000,duration:'2 horas',capacity:12,provider:'Aventura Pucón',rating:'4,8',includes:['Equipo completo','Guía','Traslado local'],requirements:'Desde 12 años. Saber nadar.',cancel:'Cancelación flexible hasta 24 horas antes.',img:'https://images.unsplash.com/photo-1530866495561-507c9faab2ed?auto=format&fit=crop&w=1000&q=80',description:'Descenso guiado por el río Trancura con equipamiento y acompañamiento durante toda la actividad.'},
{id:102,name:'Cabalgata Bosque y Volcán',commune:'Pucón',region:'Araucanía',category:'Naturaleza',price:32000,duration:'3 horas',capacity:8,provider:'Rutas del Sur',rating:'4,9',includes:['Caballo','Guía local','Casco'],requirements:'Actividad apta para principiantes.',cancel:'Cancelación flexible hasta 24 horas antes.',img:'https://images.unsplash.com/photo-1553284965-83fd3e82fa5a?auto=format&fit=crop&w=1000&q=80',description:'Recorrido a caballo por senderos rurales y bosque nativo en los alrededores de Pucón.'},
{id:103,name:'Trekking Mirador Volcánico',commune:'Pucón',region:'Araucanía',category:'Trekking',price:18000,duration:'4 horas',capacity:10,provider:'Senderos Araucanía',rating:'4,7',includes:['Guía','Bastones','Snack'],requirements:'Condición física media y calzado adecuado.',cancel:'Cancelación flexible hasta 24 horas antes.',img:'https://images.unsplash.com/photo-1551632811-561732d1e306?auto=format&fit=crop&w=1000&q=80',description:'Caminata guiada por senderos de bosque con vistas panorámicas de la zona lacustre.'},
{id:104,name:'Kayak Lago Villarrica',commune:'Pucón',region:'Araucanía',category:'Agua',price:22000,duration:'90 minutos',capacity:10,provider:'Lago Activo',rating:'4,8',includes:['Kayak','Remo','Chaleco salvavidas'],requirements:'Desde 10 años acompañado por un adulto.',cancel:'Cancelación flexible hasta 24 horas antes.',img:'https://images.unsplash.com/photo-1544551763-46a013bb70d5?auto=format&fit=crop&w=1000&q=80',description:'Salida recreativa en kayak por el Lago Villarrica con instrucciones iniciales y equipo incluido.'}
];
let experiences=JSON.parse(localStorage.getItem('findeExperiences')||'null')||experienceSeed;
let experienceReservations=JSON.parse(localStorage.getItem('findeExperienceReservations')||'[]');
let exs={dest:'Pucón',date:'',people:2};
function saveExperienceReservations(){localStorage.setItem('findeExperienceReservations',JSON.stringify(experienceReservations))}
function expCode(id){return 'FX-'+String(id).slice(-6)}
function experienceCard(x){return `<div class="card clickable" onclick="experienceDetail(${x.id})"><img src="${x.img}"><div class="pad"><span class="experience-category">${x.category}</span><h3>${x.name}</h3><p class="muted">📍 ${x.commune} · ${x.duration} · ★ ${x.rating}</p><span class="price">${money(x.price)} / persona</span><div class="openhint">Ver experiencia →</div></div></div>`}
function experiencesHome(){A.innerHTML=`<section class="experience-hero"><div><span class="experience-pill">EXPERIENCIAS FINDE</span><h1>Vive más en tu destino</h1><p>Encuentra actividades, tours y panoramas para complementar tu estadía.</p></div><div class="experience-search"><label>DESTINO<input id="exDest" value="${exs.dest}" placeholder="Ej. Pucón"></label><label>FECHA<input id="exDate" type="date" value="${exs.date}"></label><label>PERSONAS<input id="exPeople" type="number" min="1" value="${exs.people}"></label><button onclick="searchExperiences()">Buscar</button></div></section><section class="section"><div class="section-title-row"><div><h2>Experiencias en Pucón</h2><p class="muted">Aventura, naturaleza y actividades para sumar a tu viaje.</p></div></div><div class="cards">${experiences.map(experienceCard).join('')}</div></section><section class="section experience-cross"><h2>Un viaje, todo en Finde</h2><p>Reserva tu alojamiento y luego agrega actividades para las mismas fechas.</p><button onclick="home()">Buscar alojamiento</button></section>`;scrollTo(0,0)}
function searchExperiences(){exs.dest=(document.getElementById('exDest').value||'').trim();exs.date=document.getElementById('exDate').value;exs.people=Math.max(1,Number(document.getElementById('exPeople').value)||1);let r=experiences.filter(x=>!exs.dest||(x.commune+' '+x.region).toLowerCase().includes(exs.dest.toLowerCase()));A.innerHTML=`<section class="results"><span class="back" onclick="experiencesHome()">← Modificar búsqueda</span><h1>Experiencias ${exs.dest?'en '+exs.dest:''}</h1><p class="muted">${r.length} resultado(s)${exs.date?' · '+fmt(exs.date):''} · ${exs.people} persona(s)</p><div class="cards">${r.length?r.map(experienceCard).join(''):'<div class="box"><h3>No encontramos experiencias en ese destino.</h3><p class="muted">Por ahora la demo tiene oferta turística en Pucón.</p></div>'}</div></section>`;scrollTo(0,0)}
function experienceDetail(id){let x=experiences.find(v=>v.id==id);if(!x)return;A.innerHTML=`<section class="detailpage"><span class="back" onclick="experiencesHome()">← Experiencias</span><div class="experience-detail-hero"><img src="${x.img}"><div><span class="experience-category">${x.category}</span><h1>${x.name}</h1><p>📍 ${x.commune}, ${x.region} · ★ ${x.rating}</p><p>${x.description}</p></div></div><div class="detailgrid"><div><div class="facts"><div><b>${x.duration}</b><span>Duración</span></div><div><b>${x.capacity}</b><span>Cupo máximo</span></div><div><b>★ ${x.rating}</b><span>Valoración demo</span></div></div><h2>Qué incluye</h2><div class="amenities">${x.includes.map(a=>`<span>✓ ${a}</span>`).join('')}</div><h2>Información importante</h2><p>${x.requirements}</p><p><b>Cancelación:</b> ${x.cancel}</p><p><b>Prestador:</b> ${x.provider}</p></div><div class="bookingbox"><h2>${money(x.price)} <small>/ persona</small></h2><label>Fecha</label><input id="expDate" type="date" value="${exs.date}"><label>Personas</label><input id="expPeople" type="number" min="1" max="${x.capacity}" value="${Math.min(exs.people,x.capacity)}"><div id="expTotal" class="booking-summary">Total estimado: <b>${money(x.price*Math.min(exs.people,x.capacity))}</b></div><button onclick="experienceBooking(${x.id})">Reservar experiencia</button><p class="muted">Reserva demostrativa. No se realiza un cobro real.</p></div></div></section>`;let d=document.getElementById('expDate'),p=document.getElementById('expPeople');let upd=()=>document.getElementById('expTotal').innerHTML='Total estimado: <b>'+money(x.price*(Number(p.value)||1))+'</b>';p.oninput=upd;scrollTo(0,0)}
function experienceBooking(id){let x=experiences.find(v=>v.id==id),date=document.getElementById('expDate').value,people=Math.max(1,Number(document.getElementById('expPeople').value)||1);if(!date){alert('Selecciona la fecha de la experiencia.');return}if(people>x.capacity){alert('Esta experiencia admite hasta '+x.capacity+' personas.');return}exs.date=date;exs.people=people;A.innerHTML=`<section class="form experience-checkout"><span class="back" onclick="experienceDetail(${id})">← Volver</span><h1>Confirma tu experiencia</h1><div class="booking-summary"><b>${x.name}</b><p>${fmt(date)} · ${people} persona(s) · ${x.duration}</p><h3>${money(x.price*people)}</h3></div><label>Nombre</label><input id="exName" placeholder="Nombre y apellido"><label>Tipo de documento</label><select id="exDocType"><option>RUT</option><option>DNI</option><option>Pasaporte</option></select><label>Número de documento</label><input id="exDoc" placeholder="Documento"><label>Correo</label><input id="exEmail" type="email" placeholder="correo@ejemplo.cl"><label>Teléfono</label><input id="exPhone" placeholder="+56 9..."><label class="terms"><input id="exTerms" type="checkbox"> Acepto las condiciones de la reserva.</label><button onclick="confirmExperience(${id})">Confirmar reserva</button></section>`;scrollTo(0,0)}
function confirmExperience(id){let x=experiences.find(v=>v.id==id),name=document.getElementById('exName').value.trim(),email=document.getElementById('exEmail').value.trim(),phone=document.getElementById('exPhone').value.trim(),docType=document.getElementById('exDocType').value,docNumber=document.getElementById('exDoc').value.trim();if(!name||!validEmail(email)||!phone||!validDocument(docType,docNumber)||!document.getElementById('exTerms').checked){alert('Completa tus datos, usa un correo válido y acepta las condiciones.');return}let r={id:Date.now(),experienceId:id,experienceName:x.name,provider:x.provider,commune:x.commune,date:exs.date,people:exs.people,total:x.price*exs.people,guest:name,email,phone,docType,docNumber,status:'Confirmada',created:new Date().toISOString()};experienceReservations.push(r);saveExperienceReservations();A.innerHTML=`<section class="form"><div class="success"><div class="findito-celebration"><img src="findito.png" alt="Findito celebrando"><div><span class="findito-label">FINDITO CELEBRA CONTIGO</span><h2>✓ Experiencia reservada</h2></div></div><p class="confirmation-code">Código ${expCode(r.id)}</p><p><b>${name}</b>, tu reserva para <b>${x.name}</b> quedó registrada.</p><p>${fmt(r.date)} · ${r.people} persona(s) · ${x.duration}</p><h3>Total: ${money(r.total)}</h3><p>En la plataforma real enviaremos la confirmación y las instrucciones del prestador por correo.</p></div><button onclick="experiencesHome()">Ver más experiencias</button> <button class="outline" onclick="home()">Buscar alojamiento</button></section>`;scrollTo(0,0)}
function adminExperienceReservations(){adminShell('Experiencias','Reservas de experiencias','Reservas de tours y actividades realizadas desde Finde.',`<div class="admin-card">${experienceReservations.length?experienceReservations.slice().reverse().map(r=>`<div class="admin-table-row"><span><b>${expCode(r.id)}</b><small>${r.guest}</small></span><span><b>${r.experienceName}</b><small>${r.provider} · ${fmt(r.date)}</small></span><span><b>${money(r.total)}</b><small>${r.people} persona(s)</small></span><span class="tag">${r.status}</span></div>`).join(''):'<p class="muted">Todavía no hay reservas de experiencias.</p>'}</div>`)}

home();
